window.kbPageData["views/entry/k-7208cc93f1335234"] = {"key":"entry/k-7208cc93f1335234","state":{"route":"entry/k-7208cc93f1335234"},"node":{"id":"k-7208cc93f1335234","mode":"k","title":"《求是》第 10 期《做强做优做大实体经济》（5 月 16 日）","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["industry"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["重要文章"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《求是》第 10 期《做强做优做大实体经济》（5 月 16 日）","slug":"a3437b113b15"}],"directorySummary":"考点十 《求是》第 10 期《做强做优做大实体经济》（5 月 16 日）\n指出实体经济是一国经济的立身之本、财富创造的根本源泉、国家强盛的重要支柱，是我国经\n济发展和在国际经济竞争中赢得主动的根基；我国经济靠实体经济起家，也要靠实体经济走向\n未来，坚持把发展经济的着力点放在实体经济上，推动资源要素向…","sources":[{"id":"cdc6f2f93572d09d","label":"《求是》第 10 期《做强做优做大实体经济》（5 月 16 日）","topic":"重要文章","category":"时政","text":"考点十 《求是》第 10 期《做强做优做大实体经济》（5 月 16 日）\n指出实体经济是一国经济的立身之本、财富创造的根本源泉、国家强盛的重要支柱，是我国经\n济发展和在国际经济竞争中赢得主动的根基；我国经济靠实体经济起家，也要靠实体经济走向\n未来，坚持把发展经济的着力点放在实体经济上，推动资源要素向实体经济集聚、政策措施向\n实体经济倾斜、工作力量向实体经济加强。\n强调制造业是实体经济的基础，要坚定不移建设制造强国；坚持把金融服务实体经济作为根本\n宗旨，实体经济是金融的根基，金融是实体经济的血脉，服务实体经济是金融的天职，决不能\n脱实向虚。","source":{"doc":"4e539a366dce19555ccf","first":19,"last":19,"page":19,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"industry","title":"产业升级与新质生产力"}],"units":{"k-7208cc93f1335234":[]}};
